#!/usr/bin/env python3
"""Render tables directly from completed broad benchmark artifacts."""
import argparse,json,statistics
from pathlib import Path
from collections import defaultdict

LABELS={'bulkparse':'BulkParse 0.1.0','anydoc':'AnyDoc 0.2.4','pdf-inspector':'pdf-inspector 1.25.2','liteparse':'LiteParse 2.18.0','opendataloader':'OpenDataLoader 2.5.22','pymupdf4llm':'PyMuPDF4LLM 2.1 — native','pymupdf4llm-layout':'PyMuPDF4LLM 2.1 — learned layout','markitdown':'MarkItDown 0.1.9','docling':'Docling 2.150.0','pandoc':'Pandoc 3.9','mammoth':'Mammoth 1.13.0'}
def read(p):return json.loads(p.read_text())
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def write(p,text):p.write_text(text+'\n')

def main():
    ap=argparse.ArgumentParser();ap.add_argument('report',type=Path);a=ap.parse_args();p=a.report
    pdf=read(p/'pdf/summary.json');office=read(p/'office/summary.json');quality=read(p/'office/quality-results.json')['totals'];shared=read(p/'office/shared-subsets.json');holdout=read(p/'fresh-w3c/results.json');ocr=read(p/'ocr/summary.json')
    pdfrows=[]
    for e,r in sorted(pdf.items(),key=lambda x:x[1]['median_seconds']):
        m=r['metrics'];pdfrows.append([LABELS[e],*[f'{m[k+"_mean"]:.3f}' for k in ['overall','nid','teds','mhs']],f"{r['median_seconds']:.3f}",f"{r['resources']['lifetime_peak_rss_bytes']/2**20:.1f}",f"{r['returned']}/{r['attempted']}"])
    pdf_table=table(['Engine / profile','Overall','NID','TEDS','MHS','Seconds / 200 PDFs','Peak RSS MiB','Returned'],pdfrows);write(p/'pdf-table.md',pdf_table)
    office_table=table(['Engine','Returned / attempted','Median subset ms','Peak RSS MiB','Selected checks passed / applicable'],[[LABELS[e],f"{r['returned']}/{r['attempted']}",f"{r['median_seconds']*1000:.3f}",f"{r['resources']['lifetime_peak_rss_bytes']/2**20:.1f}",(f"{quality[e]['passed']}/{quality[e]['applicable']}" if quality[e]['applicable'] else "—")] for e,r in office.items()]);write(p/'office-table.md',office_table)
    fmts=sorted({f for r in office.values() for f in r['per_format']})
    formatrows=[]
    for fmt in fmts:
        row=[fmt.upper()]
        for e in office:
            r=office[e]['per_format'].get(fmt);row.append('—' if not r else f"{r['median_seconds']*1000:.3f} ({r['returned']}/{r['attempted']})")
        formatrows.append(row)
    format_table=table(['Format / total ms (returned/attempted)',*office],formatrows);write(p/'office-per-format.md',format_table)
    timing_table=table(['PDF engine','Five measured seconds','Range seconds','Outputs identical across measured passes'],[[LABELS[e],', '.join(f'{x:.3f}' for x in r['measured_seconds']),f"{min(r['measured_seconds']):.3f}–{max(r['measured_seconds']):.3f}",str(r['deterministic'])] for e,r in pdf.items()])
    holdrows=[]
    for mode in ['pdf','office']:
        for e in dict.fromkeys(r['engine'] for r in holdout if r['mode']==mode):
            chosen=[r for r in holdout if r['mode']==mode and r['engine']==e]
            holdrows.append([mode,LABELS[e],f"{sum(r['ok'] for r in chosen)}/{len(chosen)}",f"{sum(r['passed'] for r in chosen)}/{sum(r['total'] for r in chosen)}"])
    holdtable=table(['Track','Engine','Returned','Spot checks passed/applicable'],holdrows);write(p/'holdout-table.md',holdtable)
    ocrrows=[]
    for r in sorted(ocr,key=lambda x:x['median_wall_seconds']):
        q=r['quality']
        ocrrows.append([r['profile'],f"{100*q['character_error_rate']:.2f}%",f"{100*q['word_error_rate']:.2f}%",f"{r['median_wall_seconds']:.2f}",f"{r['median_cpu_seconds']:.2f}",f"{r['peak_rss_bytes']/2**20:.1f}",str(r['error_documents_first_pass'])])
    ocrtable=table(['OCR profile','CER ↓','WER ↓','Warm seconds / 24 cases','CPU seconds','Peak RSS MiB','Errors'],ocrrows);write(p/'ocr-table.md',ocrtable)
    lines=['# Broader benchmark — November 12, 2026','','Measured on Apple M3 Max, 36 GiB RAM, 14 logical CPUs, macOS. The production parser was not modified for this evaluation. These results compare explicit configurations and workloads, not universal product quality.','', '## PDF: 200 documents, OCR disabled','',pdf_table,'','Native profiles use no learned PDF layout. Docling uses Heron/TableFormer with four configured CPU threads; the PyMuPDF4LLM learned-layout row uses its default layout mode with OCR disabled. Other profiles request one thread. MarkItDown uses a format-detection model, not an OCR/layout model.','', 'All 200 inputs remain in scoring, including empty predictions for failed attempts. NID covers 200 documents, TEDS 42 and MHS 107. Overall averages available metrics per document. All BulkParse results declare partial coverage. The corpus has informed parser development; these scores are not an unseen generalization estimate.','',timing_table,'','Memory includes initialization, warm-up and all measured passes. Startup/model loading is excluded from warm timings. See [protocol](../../benchmarks/broad/README.md) and [effective options](pdf/effective-options.json).','', '## Office and EPUB: 92 inputs','',office_table,'','Each row has a different supported subset. Do not rank these total times, memory figures or selected-check fractions as equivalent whole-document workloads. Pandoc includes a CLI launch per document. Other workers persist, but Docling also launches LibreOffice for legacy conversion and fallback drawing rasterization; that cost is included. Memory is the value reported by macOS time, not summed process-tree memory.','', 'Docling now exercises its declared DOC/DOCX/RTF, XLS/XLSX, PPT/PPTX, OpenDocument and EPUB backends. This corrects the earlier adapter restriction to XLSX/PPTX. Its convert_all API retains successful chapter outputs when EPUB is detected as a generic ZIP, with HTML enabled for members. Default Markdown exports are joined with blank lines and member failures mark the document partial. The OpenDocument dependency is installed; legacy conversions use LibreOfficeDev 26.8.0.0.alpha0 (2c87e51). An incomplete attempt with missing dependencies is excluded and retained for audit. Unsupported formats are excluded and recorded; attempted failures stay in timing and quality records. MarkItDown is configured for the declared DOCX/XLS/XLSX/PPTX/EPUB extensions in this run; macro/alias variants are not tested for it.','', '### Per-format totals','',format_table,'','Each cell is the median full-format conversion time in milliseconds, with returned/attempted counts. Compare within a row, taking failures into account.','', '### Identical subsets','']
    for s in shared:
        lines.extend([f"Engines: {', '.join(s['engines'])}. Shared attempted inputs: **{s['attempted']}**; returned by all engines in every pass: **{s['returned_by_every_engine_every_pass']}**.",'',table(['Engine','Shared attempted ms','Common returned-only ms'],[[LABELS[e],f"{v['median_attempted_seconds']*1000:.3f}",f"{v['median_common_returned_seconds']*1000:.3f}"] for e,v in s['times'].items()]),''])
    lines.extend(['Returned-only subsets are selected after conversion and can favor engines that reject harder files; their timings are supplementary. The 85 existing source-grounded checks were developed alongside the parser and favor particular semantic representations, including four explicit HTML-table checks. They are not a blind LLM judge or a whole-document accuracy percentage. The appended 11 DOCX fixtures have no added quality score in this development-check set. These are small development fixtures, including minimal and edge-case packages that some parsers reject, not a representative production-document corpus or a reproduction of AnyDoc’s private 100-document study. One DOCX fixture repeats an image reference 70 times and triggers Docling’s LibreOffice rendering fallback; see per-document times before extrapolating the DOCX total. See [individual checks](office/quality-results.json).','', '## Newly added W3C spot checks','',holdtable,'','The inputs are three PDFs plus a DOCX and ODT from W3C accessibility working examples. No exact input hash appeared in the previously recorded manifests searched before conversion. Expected order and table cells were fixed before running engines; parser rules were not changed. The two column documents are related examples, as are the three table documents. This tiny, narrow set does not establish broad generalization. See [input URLs, hashes and expected cells](fresh-w3c/spec-before-conversion.json) and [per-document outcomes](fresh-w3c/results.json). [BulkParse’s two remaining gaps](fresh-w3c/remaining-gaps.md) are documented. An output-filename collision between DOCX and ODT was corrected from the original raw responses, verified against hashes recorded during conversion; [artifact audit](fresh-w3c/artifact-correction.json). No extracted content or check outcome changed.','', '## OCR engine profiles, evaluated separately','',ocrtable,'','Linux ARM64 Docker containers on this same Mac, one CPU quota and 4 GiB memory limit, network disabled. One warm-up and five full sequential passes per profile; profiles run one at a time. CER/WER are micro error rates, lower is better, with case/accent/punctuation preserved after Unicode/whitespace normalization. Errors remain empty outputs.','', 'These four deployment profiles cover RapidOCR (small), RapidOCRLite (tiny), native PaddleOCR (tiny) and Tesseract (fast language data). Model sizes differ, so the result compares configurations, not inference-framework efficiency on identical models. The existing 24 authored cases/26 pages cover nine languages and correlated degradations; they do not represent production multilingual documents. This OCR-stage test excludes PDF rendering and BulkParse layout reconstruction, and does not measure the current integrated adaptive detector.','', 'Warm wall/CPU times exclude initialization, container startup and IPC. Memory includes initialization and all passes. Raw startup measurements and per-language quality remain in [OCR summary](ocr/summary.json). These are ARM64 guest measurements, not x86 production-server results. See [OCR protocol](../../benchmarks/ocr-alternatives/README.md).','', '## Reproduce and inspect','', '- [Expanded protocol and commands](../../benchmarks/broad/README.md)','- [PDF source hashes and frozen sources](pdf/source-manifest.json), [machine and commands](pdf/identity.json), [package versions](pdf/comparators-requirements.txt)','- [PDF scores and timings](pdf/summary.json), [Office scores and timings](office/summary.json), [shared input subsets](office/shared-subsets.json)','- Each engine/round retains its predictions, statuses, errors and timing. Scored rounds retain the original evaluator output. Upstream input documents and model weights are referenced by hashes and not redistributed. The authored OCR reference text and rendered images are included under ocr/data.','', 'No comparison here substantiates a blanket “better everywhere” claim. The July 2026 numbers cited earlier used different software versions and an Apple M4 Pro; they are historical context, not same-machine timing baselines.'])
    write(p/'README.md','\n'.join(lines))

if __name__=='__main__':main()
